function mount(){const host=$('workFirstDashboard');if(!host||$('clinicCareInbox'))return;const box=document.createElement('section');box.id='clinicCareInbox';box.className='care-inbox';box.innerHTML='<header><div><small>오늘의 업무</small><h2>지금 확인할 업무</h2><p>상담·연결 승인·발송·일정 충돌을 한곳에서 확인합니다.</p></div><button type="button" class="btn" id="clinicCareRefresh">업무 새로고침</button></header><nav aria-label="업무 종류"></nav><p role="status" id="clinicCareStatus"></p><div id="clinicCareRows"></div>';host.querySelector('.work-first-head')?.after(box);if(!box.isConnected)host.prepend(box);$('clinicCareRefresh').onclick=load;const more=document.createElement('details');more.className='care-work-more';more.innerHTML='<summary>진료·예방·기존 업무 더 보기</summary>';host.append(more);for(const n of [...host.children])if(n!==box&&n!==more&&(n.matches('.work-first-kpis,.work-first-content')||n.id==='r61-today-overview'))more.append(n);render();}
