async function readInbox(path,current){const controller=new AbortController();let rejectDeadline;const expired=new Promise((_,reject)=>rejectDeadline=reject);const slow=setTimeout(()=>{if(current())$('clinicCareStatus').textContent='연결 확인 중… 기존 목록을 표시합니다. 조회 완료 후 작업할 수 있습니다.';},6000),deadline=setTimeout(()=>{controller.abort();rejectDeadline(Error('업무 조회 시간 초과 · 업무 새로고침으로 다시 확인해주세요.'));},20000);try{return await Promise.race([api(path,{signal:controller.signal}),expired]);}finally{clearTimeout(slow);clearTimeout(deadline);}}
