 const daily=frequency.match(/^하루\s*([1-6])\s*회$/),eod=/^(?:EOD(?:\s*·\s*2일에\s*1회)?|격일|2일에\s*1회)$/i.test(frequency);
 if(!daily&&!eod)throw Object.assign(Error('투약 횟수는 빠른 설정을 선택하거나 “하루 2회”처럼 입력해주세요. 필요 시 투약은 정기 일정으로 등록할 수 없습니다.'),{field:'frequency'});
 if((daily&&Number(daily[1])!==times.length)||(eod&&times.length!==1))throw Object.assign(Error('투약 횟수와 등록된 시간 개수를 맞춰주세요.'),{field:'times'});
 if(!Number.isInteger(intervalDays)||intervalDays<1||intervalDays>14||(eod&&intervalDays!==2))throw Object.assign(Error('투약일 간격을 확인해주세요. EOD는 2일 간격입니다.'),{field:'interval'});
 if(!Number.isInteger(duration)||duration<1||duration>90)throw Object.assign(Error('투약 기간은 1~90일로 입력해주세요.'),{field:'duration'});
 const start=new Date(startDate+'T00:00:00Z');if(!/^20\d{2}-\d{2}-\d{2}$/.test(startDate)||!Number.isFinite(start.getTime())||start.toISOString().slice(0,10)!==startDate)throw Object.assign(Error('관리 시작일을 확인해주세요.'),{field:'start'});
