 function get(){const m={};for(const k of ['name','dose','frequency','times','meal','duration','note'])m[k]=field(k)?.value?.trim()||'';m.pendingTime=card()?.querySelector('[data-med-time-input]')?.value||'';return m;}
 function changed(){const preview=card()?.querySelector('[data-med-name-preview]');if(preview)preview.textContent=field('name').value.trim()||'약 이름을 입력하세요';onChange(get());}
 function set(m={}){const duration=String(m.duration||'').match(/^(\d{1,2})(?:일)?$/)?.[1]||'';host.innerHTML=medicationCardHtml({...m,duration},0);card().querySelector('.med-card-actions')?.remove();for(const k of ['name','dose','frequency','duration'])field(k).required=true;for(const k of ['name','dose','frequency','times','meal','duration','note'])field(k).setAttribute('aria-label',({name:'약 이름',dose:'1회 용량',frequency:'투약 횟수',times:'등록된 투약 시간',meal:'식사 관계',duration:'투약 기간 (일수)',note:'메모'})[k]);const note=field('duration').parentElement.querySelector(':scope > small');if(note)note.textContent='시작일부터 이 일수에 맞춰 종료일이 계산됩니다.';changed();}
 function writeTimes(times){if(times.length>6){onError('투약 시간은 최대 6개까지 등록할 수 있습니다.');return false;}setMedicationRowTimes(card(),times);changed();return true;}
 function add(time){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time||'')){onError('추가할 투약 시간을 선택해주세요.');return;}const times=parseMedTimes(field('times').value);if(times.includes(time)){onError(time+'은 이미 등록된 시간입니다.');return;}if(writeTimes([...times,time]))card().querySelector('[data-med-time-input]').value='';}
